<a href="{@url}" target="_blank" rel="noopener noreferrer" class="FoFUpload--Upl-Image-Preview-Link"><img class="FoFUpload--Upl-Image-Preview" src="{@thumbnail_url}" title="{@title}" alt="{@alt}" data-id="{@uuid}" loading="lazy"><xsl:if test="@width and @height"><xsl:attribute name="width"><xsl:value-of select="@width"/></xsl:attribute><xsl:attribute name="height"><xsl:value-of select="@height"/></xsl:attribute></xsl:if></img></a>
